export class InventarioComponent {
  constructor(inventarioService) {
    this.inventarioService = inventarioService;
    this.inventario = [];
  }

  ngOnInit() {
    this.cargarInventario();
  }

  cargarInventario() {
    this.inventarioService.obtenerInventario().subscribe(data => {
      this.inventario = data;
    }, error => {
      console.error('Error al cargar el inventario', error);
    });
  }

  actualizarInventario(item) {
    this.inventarioService.actualizarInventario(item).subscribe(() => {
      this.cargarInventario();
    }, error => {
      console.error('Error al actualizar el inventario', error);
    });
  }

  eliminarInventario(itemId) {
    this.inventarioService.eliminarInventario(itemId).subscribe(() => {
      this.cargarInventario();
    }, error => {
      console.error('Error al eliminar el inventario', error);
    });
  }

}
